DO $p$ DECLARE r record; BEGIN
  SELECT * INTO r FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000001';
  IF r IS NULL THEN RAISE EXCEPTION 'PG-PF1-01 project d0f10000-0000-4000-8000-000000000001 is absent from the classification'; END IF;
  IF (r.exclusion_reason)::text IS DISTINCT FROM NULL THEN RAISE EXCEPTION 'PG-PF1-01 exclusion_reason measured=% expected=NULL', coalesce((r.exclusion_reason)::text, 'NULL'); END IF;
  IF (r.run_id)::text IS DISTINCT FROM 'e0f10000-0000-4000-8000-000000000001' THEN RAISE EXCEPTION 'PG-PF1-01 run_id measured=% expected=e0f10000-0000-4000-8000-000000000001', coalesce((r.run_id)::text, 'NULL'); END IF;
  IF (r.run_version)::text IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'PG-PF1-01 run_version measured=% expected=1', coalesce((r.run_version)::text, 'NULL'); END IF;
  IF (r.review_id)::text IS DISTINCT FROM 'f0f10000-0000-4000-8000-000000000001' THEN RAISE EXCEPTION 'PG-PF1-01 review_id measured=% expected=f0f10000-0000-4000-8000-000000000001', coalesce((r.review_id)::text, 'NULL'); END IF;
  IF (r.methodology_version)::text IS DISTINCT FROM 'v1.0.0' THEN RAISE EXCEPTION 'PG-PF1-01 methodology_version measured=% expected=v1.0.0', coalesce((r.methodology_version)::text, 'NULL'); END IF;
  IF (round(r.sroi_ratio, 4))::text IS DISTINCT FROM '3.0000' THEN RAISE EXCEPTION 'PG-PF1-01 sroi_ratio measured=% expected=3.0000', coalesce((round(r.sroi_ratio, 4))::text, 'NULL'); END IF;
  IF (round(r.total_investment, 4))::text IS DISTINCT FROM '100.0000' THEN RAISE EXCEPTION 'PG-PF1-01 total_investment measured=% expected=100.0000', coalesce((round(r.total_investment, 4))::text, 'NULL'); END IF;
  IF (round(r.net_social_value, 4))::text IS DISTINCT FROM '300.0000' THEN RAISE EXCEPTION 'PG-PF1-01 net_social_value measured=% expected=300.0000', coalesce((round(r.net_social_value, 4))::text, 'NULL'); END IF;
  IF (r.readiness_score)::text IS DISTINCT FROM '80' THEN RAISE EXCEPTION 'PG-PF1-01 readiness_score measured=% expected=80', coalesce((r.readiness_score)::text, 'NULL'); END IF;
END $p$;

