DO $s$ DECLARE n int; BEGIN
  -- SENT-PF-CROSS-ORG-REVIEW: an 'approved' review row DOES exist for this run,
  -- but it belongs to the OTHER organization. If the EXISTS correlation checked
  -- only calculation_run_id and status, this project would be included.
  SELECT count(*) INTO n FROM public.sroi_run_reviews
   WHERE calculation_run_id = 'e0f10000-0000-4000-8000-000000000002' AND status = 'approved';
  IF n <> 1 THEN RAISE EXCEPTION 'PG-PF1-02 the cross-organization approval sentinel is missing (count=%) — the probe is vacuous', n; END IF;
  SELECT count(*) INTO n FROM public.sroi_run_reviews
   WHERE calculation_run_id = 'e0f10000-0000-4000-8000-000000000002' AND status = 'approved' AND organization_id = 'a0f10000-0000-4000-8000-00000000000a';
  IF n <> 0 THEN RAISE EXCEPTION 'PG-PF1-02 the sentinel review is not cross-organization after all (count=%)', n; END IF;
END $s$;

