DO $s$ DECLARE v text; BEGIN
  -- The newer run is real, is 'calculated', and carries a LARGER version. It is
  -- excluded only because no approved review exists for it.
  SELECT (version)::text INTO v FROM public.sroi_calculation_runs WHERE id = 'e0f10000-0000-4000-8000-00000000031b';
  IF v IS DISTINCT FROM '3' THEN RAISE EXCEPTION 'PG-PF1-03 the newer unapproved run is not version 3 (measured=%) — the probe is vacuous', v; END IF;
  SELECT (count(*))::text INTO v FROM public.sroi_run_reviews WHERE calculation_run_id = 'e0f10000-0000-4000-8000-00000000031b' AND status = 'approved';
  IF v IS DISTINCT FROM '0' THEN RAISE EXCEPTION 'PG-PF1-03 the newer run has an approved review after all (count=%)', v; END IF;
END $s$;

