DO $s$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.sroi_run_reviews WHERE calculation_run_id = 'e0f10000-0000-4000-8000-000000000005' AND status = 'approved';
  IF n <> 3 THEN RAISE EXCEPTION 'PG-PF1-05 expected three approved reviews on the selected run, measured=% — the tie-break is not exercised', n; END IF;
  -- The id tiebreaker is genuinely exercised: two of the three share created_at.
  SELECT count(*) INTO n FROM (
    SELECT created_at FROM public.sroi_run_reviews
     WHERE calculation_run_id = 'e0f10000-0000-4000-8000-000000000005' AND status = 'approved'
     GROUP BY created_at HAVING count(*) > 1) g;
  IF n <> 1 THEN RAISE EXCEPTION 'PG-PF1-05 no two approved reviews share a created_at, so id DESC is never reached (groups=%)', n; END IF;
END $s$;

DO $s$ DECLARE unstamped uuid; oldest uuid; greatest_id uuid; n int; BEGIN
  SELECT count(*) INTO n FROM public.sroi_run_reviews v
   WHERE v.calculation_run_id = 'e0f10000-0000-4000-8000-000000000005' AND v.status = 'approved' AND v.reviewed_at IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'PG-PF1-05b expected exactly one unstamped approved review, measured=% — a reviewed_at ordering would not be distinguishable', n; END IF;

  SELECT v.id INTO unstamped FROM public.sroi_run_reviews v
   WHERE v.calculation_run_id = 'e0f10000-0000-4000-8000-000000000005' AND v.status = 'approved' AND v.reviewed_at IS NULL;
  SELECT v.id INTO oldest FROM public.sroi_run_reviews v
   WHERE v.calculation_run_id = 'e0f10000-0000-4000-8000-000000000005' AND v.status = 'approved'
     AND v.created_at = (SELECT min(w.created_at) FROM public.sroi_run_reviews w
                          WHERE w.calculation_run_id = 'e0f10000-0000-4000-8000-000000000005' AND w.status = 'approved');
  -- PostgreSQL has no max(uuid) aggregate. The greatest id is expressed with
  -- the uuid comparison operator instead: the row no other row outranks.
  SELECT v.id INTO greatest_id FROM public.sroi_run_reviews v
   WHERE v.calculation_run_id = 'e0f10000-0000-4000-8000-000000000005' AND v.status = 'approved'
     AND NOT EXISTS (SELECT 1 FROM public.sroi_run_reviews w
                      WHERE w.calculation_run_id = v.calculation_run_id
                        AND w.status = 'approved' AND w.id > v.id);

  -- Under DESC PostgreSQL puts NULLs FIRST, so the unstamped review would win a
  -- reviewed_at ordering; it also carries the greatest id, so it would win an
  -- id-only ordering. It is the OLDEST by created_at, so the frozen rule must
  -- not select it.
  IF unstamped IS DISTINCT FROM 'f0f10000-0000-4000-8000-0000000005ff' THEN RAISE EXCEPTION 'PG-PF1-05b the unstamped review is % expected f0f10000-0000-4000-8000-0000000005ff', unstamped; END IF;
  IF oldest IS DISTINCT FROM unstamped THEN RAISE EXCEPTION 'PG-PF1-05b the unstamped review % is not the oldest (% is)', unstamped, oldest; END IF;
  IF greatest_id IS DISTINCT FROM unstamped THEN RAISE EXCEPTION 'PG-PF1-05b the unstamped review % does not carry the greatest id (% does)', unstamped, greatest_id; END IF;
  IF (SELECT review_id FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000005') IS NOT DISTINCT FROM unstamped THEN
    RAISE EXCEPTION 'PG-PF1-05b the selection picked the unstamped oldest review — this is the live pre-PF1 defect';
  END IF;
END $s$;

