DO $a$ DECLARE inv text; net text; ratio text; n int; BEGIN
  SELECT round(sum(total_investment), 4)::text, round(sum(net_social_value), 4)::text, count(*)
    INTO inv, net, n
    FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL;
  IF n <> 5 THEN RAISE EXCEPTION 'PG-PF1-08 includedCount=% expected=5', n; END IF;
  IF inv IS DISTINCT FROM '600.0000' THEN RAISE EXCEPTION 'PG-PF1-08 SUM(total_investment)=% expected=600.0000', inv; END IF;
  IF net IS DISTINCT FROM '2100.0000' THEN RAISE EXCEPTION 'PG-PF1-08 SUM(net_social_value)=% expected=2100.0000', net; END IF;
  SELECT round(sum(net_social_value) / sum(total_investment), 6)::text INTO ratio
    FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL;
  IF ratio IS DISTINCT FROM '3.500000' THEN RAISE EXCEPTION 'PG-PF1-08 portfolio ratio=% expected=3.500000', ratio; END IF;
  -- The average of the five included per-project ratios is 3.2, not 3.5.
  SELECT round(avg(sroi_ratio), 6)::text INTO ratio
    FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL;
  IF ratio IS DISTINCT FROM '3.200000' THEN RAISE EXCEPTION 'PG-PF1-08 the average-of-ratios control value is % (expected 3.200000) — the fixture no longer distinguishes the two formulas', ratio; END IF;
  -- Readiness of the SELECTED approved reviews, over included projects only.
  SELECT count(*) INTO n FROM pf1_classified
   WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL AND readiness_score IS NOT NULL;
  IF n <> 4 THEN RAISE EXCEPTION 'PG-PF1-08 legacyManualReadinessCoverage=% expected=4', n; END IF;
  SELECT round(avg(readiness_score), 4)::text INTO ratio FROM pf1_classified
   WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL AND readiness_score IS NOT NULL;
  IF ratio IS DISTINCT FROM '50.0000' THEN RAISE EXCEPTION 'PG-PF1-08 averageLegacyManualReadinessScore=% expected=50.0000', ratio; END IF;
  -- SENT-PF-UNAPPROVED-RUN and SENT-PF-LEGACY-RUN carry distinctive magnitudes
  -- precisely so their absence is ARITHMETIC, not a matter of inspection.
  SELECT count(*) INTO n FROM pf1_classified
   WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL
     AND total_investment IN (1000000, 55555, 9000, 7000);
  IF n <> 0 THEN RAISE EXCEPTION 'PG-PF1-08 % sentinel magnitude(s) reached the included population', n; END IF;
END $a$;

DO $i$ DECLARE r record; expected text; BEGIN
  FOR r IN SELECT project_id, exclusion_reason, total_investment, run_id
             FROM pf1_classified
            WHERE project_id IN ('d0f10000-0000-4000-8000-000000000010', 'd0f10000-0000-4000-8000-000000000011', 'd0f10000-0000-4000-8000-000000000012')
  LOOP
    IF r.exclusion_reason IS DISTINCT FROM 'zero_or_invalid_investment' THEN
      RAISE EXCEPTION 'PG-PF1-09 project % reason=% expected=zero_or_invalid_investment', r.project_id, coalesce(r.exclusion_reason, 'NULL');
    END IF;
    IF r.run_id IS NULL THEN
      RAISE EXCEPTION 'PG-PF1-09 project % has no selected run — it collapsed into the no_run path', r.project_id;
    END IF;
  END LOOP;
  SELECT (count(*))::text INTO expected FROM pf1_classified
   WHERE project_id IN ('d0f10000-0000-4000-8000-000000000010', 'd0f10000-0000-4000-8000-000000000011', 'd0f10000-0000-4000-8000-000000000012') AND exclusion_reason = 'zero_or_invalid_investment';
  IF expected IS DISTINCT FROM '3' THEN RAISE EXCEPTION 'PG-PF1-09 matched % of 3 projects', expected; END IF;
  -- And each of the three is a genuinely different persisted shape.
  IF (SELECT total_investment FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000012') IS NOT NULL
     THEN RAISE EXCEPTION 'PG-PF1-09 the NULL-investment fixture is not NULL'; END IF;
  IF (SELECT total_investment FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000010') <> 0
     THEN RAISE EXCEPTION 'PG-PF1-09 the zero-investment fixture is not zero'; END IF;
  IF (SELECT total_investment FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000011') >= 0
     THEN RAISE EXCEPTION 'PG-PF1-09 the negative-investment fixture is not negative'; END IF;
END $i$;

DO $n$ DECLARE ratio numeric; n int; BEGIN
  SELECT count(*) INTO n FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000002';
  IF n <> 2 THEN RAISE EXCEPTION 'PG-PF1-10 the all-excluded portfolio holds % project(s), expected 2', n; END IF;
  SELECT count(*) INTO n FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000002' AND exclusion_reason IS NULL;
  IF n <> 0 THEN RAISE EXCEPTION 'PG-PF1-10 % member(s) of the all-excluded portfolio were included', n; END IF;
  SELECT sum(net_social_value) / nullif(sum(total_investment), 0) INTO ratio
    FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000002' AND exclusion_reason IS NULL;
  IF ratio IS NOT NULL THEN RAISE EXCEPTION 'PG-PF1-10 the ratio is % — it must be NULL, never 0', ratio; END IF;
END $n$;

DO $m$ DECLARE n int; v text; BEGIN
  SELECT count(DISTINCT methodology_version) INTO n
    FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL;
  IF n < 2 THEN RAISE EXCEPTION 'PG-PF1-11 the included population carries % distinct methodology version(s) — the case is not exercised', n; END IF;
  SELECT count(*) INTO n FROM pf1_classified
   WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL AND methodology_version IS NULL;
  IF n <> 0 THEN RAISE EXCEPTION 'PG-PF1-11 % included component(s) carry a NULL methodology version', n; END IF;
  SELECT methodology_version INTO v FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000004';
  IF v IS DISTINCT FROM 'v2.0.0' THEN RAISE EXCEPTION 'PG-PF1-11 the selected run of P04 reports methodology_version=% expected=v2.0.0', coalesce(v, 'NULL'); END IF;
END $m$;

DO $x$ DECLARE n int; inv text; BEGIN
  -- The sentinel exists, is approved and is perfectly eligible IN ITS OWN org.
  SELECT count(*) INTO n FROM pf1_classified
   WHERE project_id = 'd0f10000-0000-4000-8000-0000000000a1' AND exclusion_reason IS NULL AND organization_id = 'a0f10000-0000-4000-8000-00000000000b';
  IF n <> 1 THEN RAISE EXCEPTION 'PG-PF1-12 the cross-organization sentinel is not itself eligible (n=%) — the probe is vacuous', n; END IF;
  -- And it never appears in the other organization's portfolio.
  SELECT count(*) INTO n FROM pf1_classified
   WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND (project_id = 'd0f10000-0000-4000-8000-0000000000a1' OR organization_id <> 'a0f10000-0000-4000-8000-00000000000a');
  IF n <> 0 THEN RAISE EXCEPTION 'PG-PF1-12 % foreign row(s) reached the main portfolio', n; END IF;
  SELECT round(sum(total_investment), 4)::text INTO inv
    FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NULL;
  IF inv IS DISTINCT FROM '600.0000' THEN RAISE EXCEPTION 'PG-PF1-12 the included investment is % — the sentinel 777.0000 leaked in', inv; END IF;
END $x$;

DO $r$ DECLARE a record; b record; n int; BEGIN
  SELECT count(*) INTO n FROM public.sroi_reports WHERE project_id = 'd0f10000-0000-4000-8000-000000000001' AND status = 'locked';
  IF n <> 1 THEN RAISE EXCEPTION 'PG-PF1-13 the locked-report fixture is missing (n=%) — the probe is vacuous', n; END IF;
  SELECT count(*) INTO n FROM public.sroi_reports WHERE project_id = 'd0f10000-0000-4000-8000-000000000014';
  IF n <> 0 THEN RAISE EXCEPTION 'PG-PF1-13 the no-report twin carries % report(s)', n; END IF;
  SELECT * INTO a FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000001';
  SELECT * INTO b FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000014';
  IF a.exclusion_reason IS DISTINCT FROM b.exclusion_reason THEN RAISE EXCEPTION 'PG-PF1-13 reasons differ: % vs %', a.exclusion_reason, b.exclusion_reason; END IF;
  IF a.total_investment IS DISTINCT FROM b.total_investment
     OR a.net_social_value IS DISTINCT FROM b.net_social_value
     OR a.sroi_ratio IS DISTINCT FROM b.sroi_ratio THEN
    RAISE EXCEPTION 'PG-PF1-13 the locked-report project and its no-report twin do not contribute identically';
  END IF;
END $r$;

DO $q$ DECLARE r record; plan text := ''; BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                  WHERE table_schema = 'public' AND table_name = 'readiness' || '_assessments') THEN
    RAISE EXCEPTION 'PG-PF1-14 the canonical readiness table does not exist in this database — the probe is vacuous';
  END IF;
  FOR r IN EXECUTE 'EXPLAIN SELECT * FROM pf1_classified WHERE portfolio_id = ''c0f10000-0000-4000-8000-000000000001'''
  LOOP
    plan := plan || ' ' || r."QUERY PLAN";
  END LOOP;
  IF plan ILIKE '%readiness%assessments%' THEN
    RAISE EXCEPTION 'PG-PF1-14 the PF1 plan reads the canonical readiness table: %', plan;
  END IF;
  IF plan NOT ILIKE '%sroi_run_reviews%' THEN
    RAISE EXCEPTION 'PG-PF1-14 the plan does not read sroi_run_reviews at all — the probe is vacuous: %', plan;
  END IF;
END $q$;

DO $c$ DECLARE observed text; expected text := 'legacy_non_authoritative,no_approved_run,no_run,no_sroi_ratio,non_usd_currency,zero_or_invalid_investment'; n int; BEGIN
  SELECT string_agg(DISTINCT exclusion_reason, ',' ORDER BY exclusion_reason) INTO observed
    FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NOT NULL;
  IF observed IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PG-PF1-15 observed reasons [%] expected [%]', observed, expected; END IF;
  SELECT count(*) INTO n FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason IS NOT NULL;
  IF n <> 9 THEN RAISE EXCEPTION 'PG-PF1-15 excluded count=% expected=9', n; END IF;
  -- Per-reason cardinality, so a silent reclassification cannot hide behind the set.
  SELECT count(*) INTO n FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason = 'legacy_non_authoritative';
  IF n <> 2 THEN RAISE EXCEPTION 'PG-PF1-15 legacy_non_authoritative count=% expected=2', n; END IF;
  SELECT count(*) INTO n FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason = 'zero_or_invalid_investment';
  IF n <> 3 THEN RAISE EXCEPTION 'PG-PF1-15 zero_or_invalid_investment count=% expected=3', n; END IF;
  SELECT count(*) INTO n FROM pf1_classified WHERE portfolio_id = 'c0f10000-0000-4000-8000-000000000001' AND exclusion_reason = 'no_run';
  IF n <> 1 THEN RAISE EXCEPTION 'PG-PF1-15 no_run count=% expected=1', n; END IF;
END $c$;

DO $u$ DECLARE d text; BEGIN
  SELECT indexdef INTO d FROM pg_indexes
   WHERE schemaname = 'public' AND tablename = 'sroi_calculation_runs' AND indexname = 'uq_sroi_run_project_version';
  IF d IS NULL THEN RAISE EXCEPTION 'PG-PF1-16 uq_sroi_run_project_version is absent — version DESC is not a total order per project'; END IF;
  IF d !~ 'CREATE UNIQUE INDEX' OR d !~ 'project_id' OR d !~ 'version' THEN
    RAISE EXCEPTION 'PG-PF1-16 the index is not the (project_id, version) uniqueness: %', d;
  END IF;
END $u$;

DO $p$ DECLARE r record; BEGIN
  SELECT * INTO r FROM pf1_classified WHERE project_id = 'd0f10000-0000-4000-8000-000000000013';
  IF r IS NULL THEN RAISE EXCEPTION 'PG-PF1-17 project d0f10000-0000-4000-8000-000000000013 is absent from the classification'; END IF;
  IF (r.exclusion_reason)::text IS DISTINCT FROM 'no_run' THEN RAISE EXCEPTION 'PG-PF1-17 exclusion_reason measured=% expected=no_run', coalesce((r.exclusion_reason)::text, 'NULL'); END IF;
  IF (r.calculated_run_count)::text IS DISTINCT FROM '0' THEN RAISE EXCEPTION 'PG-PF1-17 calculated_run_count measured=% expected=0', coalesce((r.calculated_run_count)::text, 'NULL'); END IF;
END $p$;
DO $s$ DECLARE v text; BEGIN
  SELECT status INTO v FROM public.sroi_calculation_runs WHERE id = 'e0f10000-0000-4000-8000-000000000013';
  IF v IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'PG-PF1-17 the non-calculated run fixture has status=% expected=pending — the probe is vacuous', coalesce(v, 'NULL'); END IF;
